-- Every places row of the clubs' registered ArcGIS layers that
-- pipeline/make_dbt_staging.py stages, one row each, unfiltered: a `union
-- all by name` of every stg_<folder>__places it writes. The branch list is
-- the registry's, written by the generator from sources.json and the
-- extract's club folders, so a layer registered later joins by running it
-- again. Nothing reads this yet: every layer here is held back by its
-- sources.json row, and a mart that reads it must keep
-- int_sources__publication's verdict.
select
    source_key,
    club,
    place_key,
    name,
    category,
    geom,
    properties,
    _loaded_at
from {{ ref('stg_alaska_trails__places') }}
